QuestGuidance.Register("en",116,{
[3681]="70027220\n1\tComplete Molda's metalsmithy task\tMolda is in the Maker's Hall in Thorin's Hall. You should complete Molda's metalsmithy task.\n2\tTalk to Molda in the Maker's Hall\tMolda is in the Maker's Hall in Thorin's Hall. You should tell Molda that you have successfully completed his metalsmithy task.\n",
[3682]="70027224\n1\tComplete Tithrandi's weaponsmithy task\tTithrandi is in the Forging Hall in Thorin's Hall. You should complete Tithrandi's weaponsmithy task.\n2\tTalk to Tithrandi in Thorin's Hall\tTithrandi is in the Forging Hall in Thorin's Hall. You should speak with Tithrandi to advance as a weaponsmith.\n",
[3683]="700258A5\n1\tComplete Forgamthan's task in scroll-making\tForgamthan is in Elrond's Library in Rivendell. You should complete Forgamthan's task for your advancement as a Scholar.\n2\tTalk to Forgamthan in Elrond's Library\tForgamthan is near in Elrond's Library in Rivendell. You should speak with Forgamthan and give him news of your success in scroll-making.\n",
[3684]="70027222\n1\tComplete Forgamthan's task in scroll-making\tForgamthan is in Elrond's Library in Rivendell. You should complete Forgamthan's task for your advancement as a Scholar.\n2\tTalk to Forgamthan in Elrond's Library\tForgamthan is near in Elrond's Library in Rivendell. You should speak with Forgamthan and give him news of your success in scroll-making.\n",
[3685]="700256E2\n1\tComplete Jewel Underhill's cooking task\tJewel Underhill is next to the superior oven in Michel Delving. You should complete Jewel Underhill's cooking task.\n2\tTalk to Jewel Underhill, the Expert Cook Supplier\tJewel Underhill is next to the Superior Oven in Michel Delving. You should tell Jewel Underhill that you have successfully delivered all of the foodstuffs you made.\n",
[3686]="700271E7\n1\tComplete Jewel Underhill's cooking task\tJewel Underhill is next to the superior oven in Michel Delving. You should complete Jewel Underhill's cooking task.\n2\tTalk to Jewel Underhill, the Expert Cook Supplier\tJewel Underhill is next to the Superior Oven in Michel Delving. You should tell Jewel Underhill that you have successfully delivered all of the foodstuffs you made.\n",
[3687]="700258A2\n1\tComplete Daemirdan's jewellery-making task\tDaemirdan, a vendor of goods for expert jewellers, can be found in the Craft Hall in Esteldín. You should complete Daemirdan's jewellery-making task.\n2\tTalk to Daemirdan in the Esteldín Craft Hall\tDaemirdan is in the Esteldín Craft Hall. You should tell Daemirdan that you have successfully delivered the three crafted pieces of jewellery to folk throughout Esteldín.\n",
[3688]="700258A6\n1\tComplete Fladdan's tailoring task\tFladdan, the expert tailoring vendor, is in the Craft Hall in Esteldín. You should complete Fladdan's tailoring task.\n2\tTalk to Fladdan in the Esteldín Craft Hall\tFladdan is in the Crafting Hall in Esteldín. You should tell Fladdan that you have successfully delivered all of the tailored goods you made.\n",
[3689]="700258A8\n1\tComplete Tadhrien's woodworking task\tTadhrien is in the Crafting Hall in Esteldín. You should speak with Tadhrien about your advancement in woodworking.\n2\tTalk to Tadhrien in Esteldín\tTadhrien in the Crafting Hall in Esteldín. You should speak with Tadhrien to continue your advancement in crafting.\n",
[3690]="7002721C\n1\tComplete Daemirdan's jewellery-making task\tDaemirdan, a vendor of goods for expert jewellers, can be found in the Craft Hall in Esteldín. You should complete Daemirdan's jewellery-making task.\n2\tTalk to Daemirdan in the Esteldín Craft Hall\tDaemirdan is in the Esteldín Craft Hall. You should tell Daemirdan that you have successfully delivered the three crafted pieces of jewellery to folk throughout Esteldín.\n",
